'use client'
import {useEffect, useRef} from 'react'
import gsap from 'gsap'
import {ScrollTrigger} from 'gsap/ScrollTrigger'
import Lenis from 'lenis'

gsap.registerPlugin(ScrollTrigger)

export default function Experience(){
 const root=useRef<HTMLDivElement>(null)
 useEffect(()=>{
  const lenis=new Lenis({duration:1.15,smoothWheel:true})
  lenis.on('scroll',ScrollTrigger.update)
  const progress=document.querySelector<HTMLElement>('.progress')
  lenis.on('scroll',({progress:p}:{progress:number})=>{if(progress) progress.style.transform=`scaleY(${p})`})
  const raf=(t:number)=>{lenis.raf(t*1000);requestAnimationFrame(raf)}
  requestAnimationFrame(raf)
  const ctx=gsap.context(()=>{
   gsap.from('.hero-word',{y:130,opacity:0,duration:1.4,ease:'power4.out',stagger:.06,delay:.35})
   gsap.to('.hero-image',{yPercent:18,scale:1.1,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}})
   gsap.to('.thread',{strokeDashoffset:0,ease:'none',scrollTrigger:{trigger:'.thread-stage',start:'top 70%',end:'bottom 40%',scrub:1}})
   gsap.to('.cocoon',{rotation:12,y:-80,scale:1.15,scrollTrigger:{trigger:'.thread-stage',start:'top bottom',end:'bottom top',scrub:1}})
   gsap.utils.toArray<HTMLElement>('.chapter').forEach((el,i)=>{
    gsap.from(el.querySelectorAll('.chapter-in'),{y:70,opacity:0,duration:1,ease:'power3.out',stagger:.08,scrollTrigger:{trigger:el,start:'top 72%',toggleActions:'play none none reverse'}})
   })
   gsap.to('.horizontal-track',{xPercent:-62,ease:'none',scrollTrigger:{trigger:'.archive',start:'top top',end:'+=2200',pin:true,scrub:1,anticipatePin:1}})
   gsap.to('.gold-disc',{scale:3.2,opacity:.08,scrollTrigger:{trigger:'.manifest',start:'top bottom',end:'bottom top',scrub:1}})
   document.querySelectorAll<HTMLElement>('[data-magnetic]').forEach(el=>{
    const move=(e:MouseEvent)=>{const r=el.getBoundingClientRect();gsap.to(el,{x:(e.clientX-(r.left+r.width/2))*.12,y:(e.clientY-(r.top+r.height/2))*.12,duration:.35})}
    const leave=()=>gsap.to(el,{x:0,y:0,duration:.7,ease:'elastic.out(1,.4)'})
    el.addEventListener('mousemove',move);el.addEventListener('mouseleave',leave)
   })
  },root)
  return()=>{ctx.revert();lenis.destroy()}
 },[])
 return <div ref={root}>
  <div className="grain"/><div className="progress"/>
  <header className="floating-nav"><a href="#top" className="wordmark">COCOON <i>TALES</i></a><span>ASSAM / INDIA</span><a href="#contact" data-magnetic>INQUIRE ↗</a></header>
  <main id="top">
   <section className="hero2"><div className="hero-image"/><div className="hero-overlay"/><div className="hero-lockup"><p className="micro">A HOUSE OF ASSAMESE HERITAGE TEXTILES</p><h1>{'COCOON TALES'.split('').map((c,i)=><span className="hero-word" key={i}>{c===' '? '\u00a0':c}</span>)}</h1><div className="hero-bottom"><p>Stories woven in Assam.<br/>Heritage carried to the world.</p><a href="#thread" className="scroll-mark">SCROLL<br/><b>↓</b></a></div></div></section>
   <section id="thread" className="thread-stage"><svg className="thread-svg" viewBox="0 0 1200 900" preserveAspectRatio="none"><path className="thread-back" d="M80 20 C300 250 180 430 520 470 C820 505 760 700 1120 870"/><path className="thread" d="M80 20 C300 250 180 430 520 470 C820 505 760 700 1120 870"/></svg><div className="cocoon"/><div className="thread-copy"><span className="micro">01 / THE BEGINNING</span><h2>Before there is<br/><em>a textile,</em><br/>there is a cocoon.</h2><p>From a living fibre comes one of Assam's most distinctive materials — Muga, naturally golden and deeply rooted in place.</p></div></section>
   <section className="chapter dark-chapter"><div className="chapter-in chapter-number">02</div><div className="chapter-in chapter-big">GOLD<br/><em>IN FIBRE</em></div><div className="chapter-in chapter-side"><span className="micro">MUGA SILK / ASSAM</span><p>Not dyed gold. Born gold.</p><p className="muted">A rare material whose character comes from its origin, not from imitation.</p></div></section>
   <section className="chapter material"><div className="material-image chapter-in"><img src="/images/muga.svg"/></div><div className="material-copy"><span className="micro chapter-in">03 / MATERIAL</span><h2 className="chapter-in">The closer<br/>you look,<br/><em>the more you see.</em></h2><p className="chapter-in">Lustre. Irregularity. Density. The subtle signs of a natural fibre transformed by skilled hands.</p><a className="line-link chapter-in" href="#contact">Explore Muga sourcing ↗</a></div></section>
   <section className="archive"><div className="archive-label"><span className="micro">04 / THE ASSAM ARCHIVE</span><h2>Four expressions.<br/><em>One origin.</em></h2></div><div className="horizontal-track"><article><img src="/images/muga.svg"/><span>01 / MUGA</span><h3>Golden Heritage</h3></article><article><img src="/images/eri.svg"/><span>02 / ERI</span><h3>Peaceful Weaves</h3></article><article><img src="/images/loom.svg"/><span>03 / LOOM</span><h3>Living Craft</h3></article><article><img src="/images/contemporary.svg"/><span>04 / NEW ASSAM</span><h3>Contemporary Assam</h3></article></div></section>
   <section className="manifest"><div className="gold-disc"/><span className="micro">05 / THE BELIEF</span><h2>We believe luxury<br/>begins with <em>origin.</em></h2><p>And that the most valuable thing a textile can carry is the story of where it came from.</p></section>
   <section className="chapter people"><div className="people-image chapter-in"><img src="/images/weaver.svg"/></div><div><span className="micro chapter-in">06 / THE HANDS</span><h2 className="chapter-in">A loom is<br/>a memory<br/><em>in motion.</em></h2><p className="chapter-in">Cocoon Tales is being built around the people, techniques and places that keep Assam's textile heritage alive.</p><a className="line-link chapter-in" href="#contact">Our sourcing philosophy ↗</a></div></section>
   <section className="facts"><span className="micro">07 / WHY MUGA</span><div className="fact-grid">{[['01','Naturally golden'],['02','Remarkably strong'],['03','GI protected'],['04','Made for heirlooms'],['05','Distinctive origin'],['06','Global luxury potential']].map(x=><div key={x[0]}><b>{x[0]}</b><h3>{x[1]}</h3></div>)}</div></section>
   <section id="contact" className="contact2"><span className="micro">08 / FOR THE WORLD</span><h2>Bring Assam<br/><em>to your world.</em></h2><p>For boutiques, designers, collectors and partners seeking authentic Assamese textiles with a clear story of origin.</p><a className="big-mail" data-magnetic href="mailto:contact@cocoontales.com">contact@cocoontales.com ↗</a><footer><span>COCOON TALES</span><span>ASSAM · INDIA</span><span>© {new Date().getFullYear()}</span></footer></section>
  </main>
 </div>
}
